#!/usr/bin/env bash
# Build the "Try Josh in your browser" site for GitHub Pages.
#
#   scripts/make-try-site.sh STORE_PATH SITE_DIR CACHE_URL [COMMIT]
#
# The site is two things in one Pages deployment:
#
#   cache/   A Nix binary cache (narinfo + NAR files) holding STORE_PATH's
#            closure, signed with an ephemeral key generated by this run
#            and then discarded. GitHub Pages serves it with
#            `access-control-allow-origin: *`, which is all a browser tab
#            needs to fetch it. Paths already on cache.nixos.org are
#            still copied here so the boot never depends on Hydra having
#            built this exact nixpkgs revision.
#
#   index.html
#            A redirect to trynix.dev naming the store path, CACHE_URL,
#            and this run's public key. Store paths change every build,
#            so the README links to the stable Pages URL and each deploy
#            repoints the redirect at the newest build.
#
# An ephemeral key is enough because the trust root is this page: it is
# built by CI from main and served over HTTPS from the same origin as
# the cache it vouches for. No long-lived signing secret exists.
#
# Requires: nix (flakes), python3.
set -euo pipefail

store_path="${1:?usage: make-try-site.sh STORE_PATH SITE_DIR CACHE_URL [COMMIT]}"
site_dir="${2:?usage: make-try-site.sh STORE_PATH SITE_DIR CACHE_URL [COMMIT]}"
cache_url="${3:?usage: make-try-site.sh STORE_PATH SITE_DIR CACHE_URL [COMMIT]}"
commit="${4:-}"

case "$store_path" in
  /nix/store/*) ;;
  *) echo "make-try-site: not a store path: $store_path" >&2; exit 1 ;;
esac
[ -e "$store_path" ] || { echo "make-try-site: store path missing: $store_path" >&2; exit 1; }
cache_url="${cache_url%/}"

work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT

mkdir -p "$site_dir/cache"
site_abs="$(cd "$site_dir" && pwd)"

nix key generate-secret --key-name josh-try-1 > "$work/secret.key"
public_key="$(nix key convert-secret-to-public < "$work/secret.key")"

nix copy \
  --to "file://$site_abs/cache?secret-key=$work/secret.key&compression=zstd" \
  "$store_path"

STORE_PATH="$store_path" CACHE_URL="$cache_url" PUBLIC_KEY="$public_key" \
COMMIT="$commit" SITE_DIR="$site_abs" \
python3 - <<'PY'
import html
import json
import os
from urllib.parse import urlencode

store_path = os.environ["STORE_PATH"]
cache_url = os.environ["CACHE_URL"]
public_key = os.environ["PUBLIC_KEY"]
commit = os.environ.get("COMMIT", "")
site_dir = os.environ["SITE_DIR"]

trynix_url = "https://trynix.dev/?" + urlencode([
    ("path", store_path),
    ("cache", f"{cache_url} {public_key}"),
    ("boot", "1"),
])

commit_line = (
    f'<p class="meta">Built from commit <code>{html.escape(commit)}</code>.</p>'
    if commit else ""
)

page = f"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Try Josh in your browser</title>
<meta http-equiv="refresh" content="0; url={html.escape(trynix_url, quote=True)}">
<style>
  body {{ font-family: ui-monospace, monospace; margin: 3rem auto; max-width: 40rem; padding: 0 1rem; line-height: 1.5; }}
  .meta {{ color: #666; font-size: 0.85em; overflow-wrap: anywhere; }}
</style>
</head>
<body>
<h1>Try Josh in your browser</h1>
<p>Redirecting to <a href="{html.escape(trynix_url, quote=True)}">trynix.dev</a>,
which boots a Linux VM in this tab with the latest <code>main</code> build
of Josh on <code>PATH</code>. When the prompt appears, type:</p>
<pre>josh</pre>
{commit_line}
<p class="meta">Store path: <code>{html.escape(store_path)}</code><br>
Binary cache: <code>{html.escape(cache_url)}</code></p>
<p class="meta"><a href="https://github.com/mbullington/josh-shell">github.com/mbullington/josh-shell</a>
&middot; powered by <a href="https://trynix.dev">trynix</a></p>
</body>
</html>
"""

with open(os.path.join(site_dir, "index.html"), "w", encoding="utf-8") as f:
    f.write(page)
with open(os.path.join(site_dir, "try.json"), "w", encoding="utf-8") as f:
    json.dump({
        "storePath": store_path,
        "cache": cache_url,
        "publicKey": public_key,
        "commit": commit or None,
        "trynixUrl": trynix_url,
    }, f, indent=2)
    f.write("\n")
with open(os.path.join(site_dir, ".nojekyll"), "w", encoding="utf-8") as f:
    f.write("")

print(trynix_url)
PY
